// Provider-agnostic LLM chat — the `llm.chat@1` slot (SERVICE_PROVIDERS_SPEC;
// LLM_AND_AGENTS_SPEC §8 D5).
//
// An app calls ONE chat slot and never worries about which provider the user has a
// key for: the HOST resolves which vendor answers from the key the user holds
// (`SecretView.boundOrigin`) plus their `preferredImplementation` choice, normalizes
// the wire format, injects the key host-side at the §6 net:fetch point (the
// look-at-nothing proxy), and streams normalized deltas back. The app never names a
// vendor, never sees the key, and needs NO `net:fetch`/`secrets` grant of its own —
// only the `llm:chat` capability (elevated, app-scoped: a fork earns it by consent).
//
// Inert until the host implements `protocol-llm` (the `chat` stream) + the
// `llm-provider` describe channel; the contract ships here so apps (the file-explorer
// summarize fork) can be written against it — exactly how `secrets.ts` shipped ahead
// of `protocol-secrets`.
import { invokeStream } from './catalog';
import { createPushChannel } from './pushChannel';
import { LLM_PROVIDER, REQUEST_LLM_PROVIDER } from './generated/protocol';

/** Who authored a {@link ChatMessage}. */
export type ChatRole = 'system' | 'user' | 'assistant' | 'tool';

/** A part of a message. `image` is only honored when the resolved provider
 *  advertises `features.vision` (§2.5); `tool-use`/`tool-result` only when it
 *  advertises `features.tools` — branch on {@link describeChat} first. */
export type ContentPart =
  | { type: 'text'; text: string }
  | { type: 'image'; mimeType: string; data: string } // data: base64, no data: URL prefix
  // A tool call the model emitted on a prior `assistant` turn — replay it in the
  // conversation so a follow-up request carries the agentic history. Pairs with the
  // streamed `tool-call` {@link ChatDelta} that first surfaced it.
  | { type: 'tool-use'; id: string; name: string; input: Record<string, unknown> }
  // A block of the model's own REASONING from a prior `assistant` turn (R3-335).
  // Honored only when the resolved provider advertises `features.reasoning`.
  //
  // Echo these back. On some providers a reasoning block must be replayed — with its
  // `signature` intact and BEFORE the turn's text/tool-use — for the following turn to
  // be accepted at all; a loop that drops them is quietly lossy across turns in a way
  // that shows up as degraded output rather than an error. Pairs with the streamed
  // `reasoning` {@link ChatDelta}.
  | { type: 'reasoning'; text: string; signature?: string }
  // Reasoning the provider REDACTED: opaque bytes with no readable text, which still
  // have to be echoed back in place to keep the chain valid. Never render it.
  | { type: 'reasoning-redacted'; data: string }
  // The result of executing a `tool-use`, fed back so the model can continue. Carried
  // on a `user`/`tool`-role message; `toolCallId` matches the `tool-use` `id`.
  | { type: 'tool-result'; toolCallId: string; content: string; isError?: boolean };

/** One message in a {@link ChatRequest}: a role plus its content parts. */
export interface ChatMessage {
  role: ChatRole;
  content: ContentPart[];
}

/** A tool the model may call — honored only when `features.tools`. */
export interface ToolDef {
  name: string;
  description?: string;
  /** JSON-Schema for the tool's arguments. */
  inputSchema: Record<string, unknown>;
}

/** A host-brokered chat completion request: the messages plus optional tools,
 *  response format, and model hint (each honored per the provider's features). */
export interface ChatRequest {
  messages: ChatMessage[];
  /** Honored only when the resolved provider advertises `features.tools`. */
  tools?: ToolDef[];
  /** `'json'` honored only when `features.jsonMode`. Defaults to `'text'`. */
  responseFormat?: 'text' | 'json';
  maxTokens?: number;
  /** An ABSTRACT tier hint, never a vendor model id — the host maps it to a concrete
   *  model on the resolved provider. Omit to take the provider's default. */
  modelHint?: 'fast' | 'smart';
  /** A concrete provider-and-model choice, naming one of the user's CONNECTED providers
   *  (R3-620, LLM_AND_AGENTS_SPEC §0 editing-session exception). When present it WINS over
   *  `modelHint`; the host validates the pair against the user's connected set and refuses
   *  with `provider-not-connected` otherwise. Only an editing-session principal may read the
   *  chooseable set (via `describeChat()`'s `connectedProviders`, gated `llm:chooseModel`);
   *  a stage app still passes at most the abstract hint. */
  model?: { providerId: string; model: string };
  /** Abort the completion mid-stream. When it fires, the SDK sends the host a cancel
   *  frame so the host aborts the upstream provider request and STOPS BILLING the
   *  user's key — not merely stops the app-side iterator (LLM_AND_AGENTS_SPEC §3.3
   *  "abort the in-flight LLM request", R3-224). Not sent over the wire (an
   *  `AbortSignal` isn't serializable); handled SDK-side. */
  signal?: AbortSignal;
}

/** One streamed chunk. Consumers typically accumulate `text-delta`s. */
export type ChatDelta =
  | { type: 'text-delta'; text: string }
  | { type: 'tool-call'; id: string; name: string; input: unknown }
  // R3-335 — the model's reasoning as it streams. `reasoning-delta` carries the text
  // incrementally (render it live); the terminal `reasoning` carries the WHOLE block
  // plus the `signature` the provider may require on the echo, and is what a caller
  // should put back into the conversation. A provider without reasoning emits neither.
  | { type: 'reasoning-delta'; text: string }
  | { type: 'reasoning'; text: string; signature?: string }
  | { type: 'reasoning-redacted'; data: string }
  // Token accounting for the turn. `cacheReadTokens`/`cacheWriteTokens` are present
  // only on providers that report prompt caching (R3-336) — they are what makes a
  // caching claim verifiable rather than believed, and their ABSENCE is meaningful:
  // it says this provider reports nothing, not that nothing was cached.
  | {
      type: 'usage';
      inputTokens: number;
      outputTokens: number;
      cacheReadTokens?: number;
      cacheWriteTokens?: number;
    };

/** Why generation stopped: natural `end`, `length` cap, a `tool` call, or content `filtered`. */
export type ChatStopReason = 'end' | 'length' | 'tool' | 'filtered';

/** The terminal value of the {@link chat} stream. */
export interface ChatResult {
  stopReason: ChatStopReason;
}

/**
 * Stream a chat completion from whichever provider the user has configured.
 *
 * ```ts
 * let summary = '';
 * for await (const d of chat({ messages: [{ role: 'user', content: [{ type: 'text', text }] }] })) {
 *   if (d.type === 'text-delta') summary += d.text;
 * }
 * ```
 *
 * Requires the `llm:chat` capability. If no provider is bound, the host first
 * draws the SP-7 connect-me gate itself (R3-456: the app never draws a
 * credential prompt — that is host chrome, SECRETS_SPEC S3):
 * - the user connects a key → the call retries once and streams normally;
 * - the user declines → the generator throws `code: 'cancelled'` (the same code
 *   a declined powerbox produces — a working degraded state: catch it and
 *   degrade, e.g. skip the AI feature);
 * - an older host without the gate throws `code: 'provider-not-configured'`.
 * A signed-out user throws `code: 'auth-required'`; an un-granted call throws
 * `forbidden`.
 */
export function chat(req: ChatRequest): AsyncGenerator<ChatDelta, ChatResult, void> {
  // Peel `signal` out of the request before it becomes wire params — an AbortSignal
  // can't cross the postMessage boundary as data; it drives the SDK-side cancel frame.
  const { signal, ...params } = req;
  return invokeStream<ChatDelta, ChatResult>('llm:chat', params as unknown as Record<string, unknown>, signal);
}

/** The resolved provider's advertised abilities (SERVICE_PROVIDERS_SPEC §2.5) — read
 *  to branch/degrade (offer image upload only when `vision`). */
export interface ChatFeatures {
  vision: boolean;
  tools: boolean;
  jsonMode: boolean;
  /** R3-335: the provider emits reasoning blocks. Read it to decide whether to render
   *  a thinking surface at all — an empty affordance on a provider that never thinks
   *  is worse than none. Normalized to `false` by the channel when a host predating
   *  R3-335 omits it, so this is never `undefined` in practice. */
  reasoning: boolean;
  maxContextTokens: number;
}

/** How the resolved provider's requests physically leave the browser. Read it to
 *  DESCRIBE routing where that matters to the person ("runs in your browser" vs
 *  "routed through immediately.run") — never to draw host chrome or a consent prompt,
 *  which remain the host's (UI_AS_APPS §8 T15). */
export type ChatExecutor = 'browser-direct' | 'backend-proxied';

/** The concrete model each abstract tier resolves to right now. */
export interface ChatTierModels {
  fast: string;
  smart: string;
}

/** One CONNECTED provider the user may choose a model from, for a per-conversation model
 *  choice in an editing-session workbench (R3-620, LLM_AND_AGENTS_SPEC §0). Names and ids
 *  only — never keys, usage, balance or routing. */
export interface ChatProviderChoice {
  /** Opaque provider id, e.g. `llm.chat.anthropic` — matches {@link ChatRequest.model}.providerId. */
  providerId: string;
  /** The provider's human name, for a picker label. */
  displayName: string;
  /** The chooseable model names — the catalogue-recommended set plus the two the user has
   *  chosen. A closed list here would re-introduce the ids-rot problem, so `model` is passed
   *  through to the adapter exactly as the Settings field is; this list is suggestions. */
  models: string[];
}

/** Info about the provider the host resolved for this app. `null` when no provider
 *  is bound (SP-7: prompt the user to add a key before calling {@link chat}). */
export interface ChatProviderInfo {
  /** Opaque provider id, e.g. `llm.chat.anthropic` — never a vendor secret or model id. */
  providerId: string;
  /** True for Host-proxied providers (host-vouched, SP-9); false for app-level ones,
   *  whose `features` are an untrusted claim. */
  hostVouched: boolean;
  features: ChatFeatures;
  /** The provider's human name, e.g. `OpenRouter` — what to put in front of a person.
   *  Absent on a host that predates the field: fall back to your own copy rather than
   *  rendering the id, which is a platform identifier and not a name. */
  displayName?: string;
  /** How this provider's requests leave the browser. Absent on a host that predates the
   *  field, which is NOT the same as `browser-direct` — say nothing about routing rather
   *  than guess at it. */
  executor?: ChatExecutor;
  /**
   * The concrete model each {@link ChatRequest.modelHint} tier resolves to — what a
   * `smart` request would actually run, after the user's own preference.
   *
   * Read-only, and it does not weaken `LLM_AND_AGENTS_SPEC §0`: an app still names no
   * model, and {@link ChatRequest} still carries only the abstract hint. It is here so an
   * app can be HONEST about what answered — a transcript that says which model wrote a
   * reply, a warning that names the model about to be spent on — instead of showing a
   * blank where the platform knows the answer. The user picks the model in host settings;
   * the app reports it.
   *
   * Absent on a host that predates the field. It changes when the user changes their
   * preference, so read it through {@link onChatProviderChange} rather than caching it.
   */
  models?: ChatTierModels;
  /**
   * The user's CONNECTED providers and their chooseable models, for a per-conversation
   * model choice (R3-620). Only present when this frame holds the ELEVATED `llm:chooseModel`
   * capability (an editing-session workbench); the host strips it for everyone else, so a
   * stage app sees `undefined` and can offer only the abstract `modelHint` path.
   *
   * Read-only: names and ids only. No keys, usage, balance or routing. Absent also on a host
   * that predates the field.
   */
  connectedProviders?: ChatProviderChoice[];
}

/**
 * Whether the host has told us about a provider yet, and if so whether one is bound —
 * and, since R3-688, whether this frame may ask at all.
 *
 * THREE states, because two is the bug (R3-300). `describeChat()` returns `null` both
 * when no provider is configured AND when the channel has not answered — so an app
 * cannot tell "you need a key" from "ask again in a moment", and consuming apps
 * rendered a misleading "connect a key" banner at users who had one. `unknown` is the
 * state before the host answers; it is not an error and not a prompt to act.
 *
 * **`unknown` is TRANSIENT — the host answers every frame** (R3-419;
 * `LLM_AND_AGENTS_SPEC §4.1` R-LLM-1..3). An app that does not hold `llm:chat` is not
 * met with silence. So it is correct to treat a `unknown` that persists as a host bug
 * rather than as a state to design around, and WRONG to render a spinner with no
 * timeout on it. (Before R3-419 the host withheld the channel entirely from an
 * ungranted frame, and `unknown` stood forever — that is the failure this note exists
 * to keep from being re-created on the app side.)
 *
 * The FOURTH state, `ungranted` (R3-688; `LLM_AND_AGENTS_SPEC §4.1` R-LLM-2 as
 * annotated, `GROVE_AGENT_SPEC` G-GA-10): the host answered, and the reason this frame
 * cannot reach a model is that **it does not hold `llm:chat`** — not that the user has
 * no key. R3-419 deliberately answered an ungranted frame with the same payload as a
 * keyless one, because the SDK could not carry the difference; that made the distinct
 * "not granted" cause the reach-card contract promises (G-GA-10) uncomputable — an
 * ungranted fork of an app rendered "connect a key" at a user who had one. The host now
 * marks the grantless answer with an optional `ungranted: true` on the SAME message
 * (additive — an older SDK never reads the field and degrades to `not-configured`;
 * an older host never sends the field and the app degrades the same way). The mark is
 * HOST-derived from the frame's resolved grant set at push time (the channel view in
 * `channelAcl.ts`), never from anything this frame asserts.
 */
export type ChatProviderState =
  | { status: 'unknown' }
  | { status: 'not-configured' }
  | { status: 'ungranted' }
  | { status: 'configured'; provider: ChatProviderInfo };

// The `llm-provider` describe channel (Recipe A): the host pushes the resolved
// provider info on change and replays it on register-frame, gated by `llm:chat`.
// A message with no `provider` key is ignored; an explicit `null` means "no provider
// bound", which is now REPRESENTABLE as distinct from "not yet answered".
// The channel's VALUE stays exactly what the wire carries — `ChatProviderInfo | null` —
// because the protocol snapshot gate reads this type as the channel's shape. The state
// read lives BESIDE it: `answered` records whether the host has ever spoken on this
// channel, which is the one bit `null` cannot carry, and `ungrantedMark` (R3-688) reads
// the host's optional grantless marker off the same message — also beside the value, not
// inside it. Deriving the state rather than widening the channel keeps the declared wire
// VALUE unchanged (SDK_PACKAGING_SPEC §9: additive-only; the optional message field
// follows the `theme`/`form-factor` insets precedent — old readers ignore it, and the
// sandbox-protocol descriptor's "read off" line catches up at its next release).
/**
 * Reconcile what the host actually sent with what this SDK declares.
 *
 * `features.reasoning` arrived after `ChatFeatures` shipped, so a host predating it
 * omits the key. `undefined` reads as falsy everywhere EXCEPT a `'reasoning' in
 * features` check, which is exactly the kind of difference that produces one wrong
 * branch a year later — so it is normalized here, once, rather than left to every
 * caller. Absent means "does not reason": the fail-closed reading.
 *
 * `displayName`, `executor` and `models` arrived later still, and for them absence is a
 * REAL answer an app is told to handle ("this host does not say"), so they are left
 * absent rather than filled in. What is dropped is a value that is present but not
 * usable — an `executor` outside the union, a `models` missing a tier — because a
 * half-answer rendered as fact is worse than the honest blank the app already handles.
 *
 * Exported for its own test; not part of the public surface (`index.ts` re-exports
 * this module wholesale, so it is reachable — it is documented as internal rather
 * than hidden behind a lie).
 * @internal
 */
const EXECUTORS: readonly ChatExecutor[] = ['browser-direct', 'backend-proxied'];

const usableModels = (raw: unknown): ChatTierModels | undefined => {
  if (!raw || typeof raw !== 'object') return undefined;
  const { fast, smart } = raw as Partial<ChatTierModels>;
  return typeof fast === 'string' && fast && typeof smart === 'string' && smart ? { fast, smart } : undefined;
};

/** Validate the wire's `connectedProviders` list, keeping only usable entries. The gating
 *  (whether the list arrives at all) is the host's — `normalizeProviderInfo` merely refuses
 *  to pass through a malformed list, exactly as it refuses a half-answered `models` pair. */
const usableConnectedProviders = (raw: unknown): ChatProviderChoice[] | undefined => {
  if (!Array.isArray(raw)) return undefined;
  const out: ChatProviderChoice[] = [];
  for (const item of raw) {
    if (!item || typeof item !== 'object') continue;
    const { providerId, displayName, models } = item as Partial<ChatProviderChoice>;
    if (typeof providerId !== 'string' || !providerId) continue;
    if (typeof displayName !== 'string' || !displayName) continue;
    const cleanModels = Array.isArray(models) ? models.filter((m): m is string => typeof m === 'string' && !!m) : [];
    out.push({ providerId, displayName, models: cleanModels });
  }
  return out.length > 0 ? out : undefined;
};

export function normalizeProviderInfo(provider: ChatProviderInfo | null): ChatProviderInfo | null {
  if (!provider) return null;
  // The LATER fields (displayName/executor/models/connectedProviders) are taken OFF the value
  // and put back only if usable — spreading and then overwriting would leave an unusable key
  // present, and `key in provider` is exactly how an app is told to ask whether the host said
  // anything.
  const {
    displayName: rawName,
    executor: rawExecutor,
    models: rawModels,
    connectedProviders: rawConnected,
    ...rest
  } = provider;
  // The wire value is whatever the host sent, which may predate any of these fields — so
  // read it as partial rather than trusting the declared type, and decide each explicitly.
  const wire = provider.features as Partial<ChatFeatures>;
  const executor = EXECUTORS.includes(rawExecutor as ChatExecutor) ? (rawExecutor as ChatExecutor) : undefined;
  const displayName = typeof rawName === 'string' && rawName ? rawName : undefined;
  const models = usableModels(rawModels);
  const connectedProviders = usableConnectedProviders(rawConnected);
  return {
    ...rest,
    features: { ...wire, reasoning: wire.reasoning === true } as ChatFeatures,
    ...(displayName ? { displayName } : {}),
    ...(executor ? { executor } : {}),
    ...(models ? { models } : {}),
    ...(connectedProviders ? { connectedProviders } : {}),
  };
}

let answered = false;
// R3-688 — the host's grantless marker, read off the SAME message (`ungranted: true`
// beside `provider`). It is message-arrival state beside `answered`, not part of the
// wire VALUE: the channel's value stays `ChatProviderInfo | null`, so the protocol
// snapshot gate keeps reading the unchanged shape.
let ungrantedMark = false;
const channel = createPushChannel<ChatProviderInfo | null>({
  pushType: LLM_PROVIDER,
  requestType: REQUEST_LLM_PROVIDER,
  initial: null,
  parse: (msg) => {
    if (!('provider' in msg)) return undefined;
    answered = true;
    ungrantedMark = msg.ungranted === true;
    return normalizeProviderInfo((msg.provider as ChatProviderInfo | null) ?? null);
  },
});

/**
 * Derive the four-state read from what the host has said. Pure, and exported for its
 * own test (`llmProviderState.test.ts`) like `normalizeProviderInfo` — not part of the
 * public surface beyond `index.ts`'s wholesale re-export.
 *
 * Order is load-bearing: `unknown` wins until the host answers (an `ungranted` mark
 * cannot exist before an answer — it arrives ON the answer); then the host's grantless
 * mark; then the provider. A host that predates the mark never sets it, so its
 * grantless answer derives `not-configured` — the exact pre-R3-688 contract, which is
 * the additive degradation the fourth state promises.
 *
 * @internal
 */
export function deriveChatProviderState(
  answered: boolean,
  ungranted: boolean,
  provider: ChatProviderInfo | null,
): ChatProviderState {
  if (!answered) return { status: 'unknown' };
  if (ungranted) return { status: 'ungranted' };
  return provider ? { status: 'configured', provider } : { status: 'not-configured' };
}

/** Derive the state from the wire value plus what the host has said beside it. */
const stateOf = (provider: ChatProviderInfo | null): ChatProviderState =>
  deriveChatProviderState(answered, ungrantedMark, provider);

/**
 * The provider the host resolved for this app, or `null`.
 *
 * Kept for compatibility (`ways_of_working §6`, additive-only): it collapses `unknown`
 * and `not-configured` to `null`. Prefer {@link describeChatState} when the difference
 * matters — which is any time you would render "connect a key", because doing that in
 * the `unknown` state is exactly the false banner R3-300 fixes.
 */
export const describeChat = (): ChatProviderInfo | null => channel.get();

/** The four-state read: `unknown` before the host answers; then the host's `ungranted`
 *  mark, or the provider (configured / not-configured). */
export const describeChatState = (): ChatProviderState => stateOf(channel.get());

/** Subscribe to provider changes (key added/revoked, preference changed). Invoked
 *  immediately with the current value, then on every change. Returns unsubscribe. */
export const onChatProviderChange = (listener: (provider: ChatProviderInfo | null) => void): (() => void) =>
  channel.onChange(listener);

/** Subscribe to the provider-state description. */
export const onChatProviderStateChange = (listener: (state: ChatProviderState) => void): (() => void) =>
  channel.onChange((p) => listener(stateOf(p)));

/** React hook returning the resolved chat provider (or `null`), re-rendering on
 *  change — gate the summarize affordance on `provider !== null`. */
export const useChatProvider = (): ChatProviderInfo | null => channel.use();

/**
 * React hook returning the four-state description.
 *
 * Use this to render provider state honestly: show nothing (or a neutral placeholder)
 * while `unknown`, the connect affordance only on `not-configured`, the NOT-GRANTED
 * cause — never the connect copy — on `ungranted`, and the provider's name on
 * `configured`.
 */
export const useChatProviderState = (): ChatProviderState => stateOf(channel.use());
